mapper.sql:
WHERE m.company_id = #{f.companyId}

	AND m.user_id = #{f.userIdEq}


	AND m.user_id IN
	#{uid}


	AND m.user_id NOT IN
	#{uid}


	AND m.inviter_id = #{f.inviterId}


	AND m.grade_id = #{f.gradeIdEq}


	AND m.user_id IN
	#{vid}


	AND m.mobile = #{f.mobileEncEq}


	AND m.remarks LIKE CONCAT('%', #{f.remarksLike}, '%')


	AND info.username = #{f.usernameLike}


	AND info.name LIKE CONCAT('%', #{f.nameLike}, '%')


	AND m.source_from = #{f.sourceEq}


	AND EXISTS (
		SELECT 1 FROM members_associations ma
		INNER JOIN members_wechatusers w ON w.company_id = ma.company_id AND w.unionid = ma.unionid
		WHERE ma.company_id = m.company_id AND ma.user_id = m.user_id AND ma.user_type = 'wechat'
		AND w.nickname LIKE CONCAT('%', #{f.wechatNicknameLike}, '%')
		LIMIT 1
	)



		AND info.have_consume = 1


		AND info.have_consume = 0



	AND info.birthday >= #{f.birthdayStart}


	AND info.birthday <= #{f.birthdayEnd}


	AND m.created >= #{f.timeStartBegin}


	AND m.created <= #{f.timeStartEnd}


	AND s.store_bn = #{f.storeBnEq}


	AND m.op_distributor = #{f.opDistributorEq}


	AND shop.shop_type = 'shop'
	AND shop.shop_id IN
	#{sid}


	AND reltags.tag_id IN
	#{tid}


	AND reltags.tag_id = #{f.tagIdEq}

FROM members m
LEFT JOIN members_info info ON m.company_id = info.company_id AND m.user_id = info.user_id

	LEFT JOIN members_rel_tags reltags ON reltags.user_id = m.user_id AND reltags.company_id = m.company_id


	LEFT JOIN point_member pm ON pm.user_id = m.user_id AND pm.company_id = m.company_id

WHERE m.company_id = #{f.companyId}

	AND m.user_id IN
	#{uid}


	AND m.grade_id = #{f.gradeIdEq}


	AND m.has_fp = #{f.hasFpEq}


	AND m.is_become_friend = #{f.isBecomeFriendEq}


	AND m.fp_salesperson = #{f.fpSalespersonEq}


	AND m.op_distributor = #{f.opDistributorEq}


	AND info.birthday >= #{f.birthdayStart}


	AND info.birthday <= #{f.birthdayEnd}


	AND pm.point >= #{f.pointGte}


	AND pm.point <= #{f.pointLte}


	AND m.mobile LIKE CONCAT('%', #{f.mobileLike}, '%')


	AND reltags.tag_id IN
	#{tid}

FROM members member
LEFT JOIN members_info info
	ON member.company_id = info.company_id AND member.user_id = info.user_id
LEFT JOIN members_associations associations
	ON member.company_id = associations.company_id AND member.user_id = associations.user_id
LEFT JOIN membercard_grade membercard_grade
	ON member.grade_id = membercard_grade.grade_id

LEFT JOIN members_rel_tags rel_tag
	ON rel_tag.company_id = member.company_id AND rel_tag.user_id = member.user_id

WHERE member.company_id = #{f.companyId}

	AND member.inviter_id IN
	#{iid}


	AND member.grade_id = #{f.gradeIdEq}


	AND member.mobile = #{f.mobileEq}


	AND member.source_from = #{f.sourceFromEq}


	AND member.disabled = #{f.disabledEq}


	AND member.user_card_code = #{f.cardCodeEq}


	AND member.created BETWEEN #{f.createdStart} AND #{f.createdEnd}


	AND member.created >= #{f.createdStart}


	AND member.created <= #{f.createdEnd}


	AND info.have_consume = #{f.haveConsumeEq}


	AND rel_salesperson.salesperson_id = #{f.salespersonIdGt}
	AND rel_salesperson.is_bind = 1
	AND rel_salesperson.company_id = #{f.companyId}


	AND rel_tag.tag_id = #{f.tagIdGt}
	AND rel_tag.company_id = #{f.companyId}


	AND vip_rel_user.vip_grade_id = #{f.vipGradeIdGt}
	AND vip_rel_user.company_id = #{f.companyId}
	AND vip_rel_user.end_date > UNIX_TIMESTAMP()
